import { network } from "./generated/index.js";
import type { OfferEnvelopeValidation } from "./interfaces/internal/offer_routing.js";

/**
 * Production envelope validation, generated by PR #12's pinned Lexicon toolchain.
 * Open payload unions still need the injected task-specific payload validator.
 */
export const lexiconOfferValidation: OfferEnvelopeValidation = {
	parseDispatch(value) {
		return network.hivemind.coordinator.dispatch.$validate(value);
	},
	parseOffer(value) {
		return network.hivemind.agent.offer.$validate(value);
	},
};
